"use strict";
// Replays cases generated by the Flutter tests (build/career_parity.json and
// build/career_journey/*.json) through the server's rules. The server must
// compute exactly the numbers the app computed. In CI the Flutter tests run
// first and CAREER_PARITY_REQUIRED=1 makes missing files a failure.

const test = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");

const BUILD = path.join(__dirname, "..", "..", "build");
const required = process.env.CAREER_PARITY_REQUIRED === "1";

function load(file) {
  if (!fs.existsSync(file)) {
    if (required) throw new Error(`${file} is missing: the Flutter tests should have written it.`);
    return null;
  }
  return JSON.parse(fs.readFileSync(file, "utf8"));
}

const R = require("../career/rules");
const { applyAction, emptyState } = require("../career/server");

const parity = load(path.join(BUILD, "career_parity.json"));

test("screening matches the app", { skip: !parity && "no parity file" }, () => {
  for (const c of parity.screening) {
    const got = R.screen(R.CATALOG.postings[c.postingId], { ...c.input, thisYear: parity.thisYear });
    assert.deepEqual(got, c.expect, `${c.postingId} ${c.input.applicationId}`);
  }
});

test("interview scores match the app", { skip: !parity && "no parity file" }, () => {
  for (const c of parity.interviews) {
    const got = R.scoreInterview(R.CATALOG.postings[c.postingId], c.applicationId, c.input);
    assert.equal(got.error, undefined, `${c.postingId}: ${got.error}`);
    assert.deepEqual(got, c.expect, `${c.postingId} ${c.applicationId}`);
  }
});

test("hiring decisions and offers match the app", { skip: !parity && "no parity file" }, () => {
  for (const c of parity.decisions) {
    const job = R.CATALOG.postings[c.postingId];
    const d = R.decide(job, c.screening, c.interview, c.assessment || null);
    assert.deepEqual({ ...d, offerSalary: R.offerSalary(job, d.overall) }, c.expect, c.postingId);
  }
});

test("negotiation matches the app", { skip: !parity && "no parity file" }, () => {
  for (const c of parity.negotiations) {
    const job = R.CATALOG.postings[c.postingId];
    assert.deepEqual(R.negotiate(job, c.salary, job.salaryPeriod, c.interviewOverall, c.message), c.expect, c.postingId);
  }
});

test("paychecks, raises and stipends match the app", { skip: !parity && "no parity file" }, () => {
  for (const c of parity.pay) {
    const got = R.paycheck(c.employment, c.period);
    assert.deepEqual({ id: got.id, grossCents: got.grossCents, deductionCents: got.deductionCents, netCents: got.netCents }, c.expect);
    for (const [f, v] of Object.entries(c.raised)) assert.equal(R.raised(c.employment.salary, c.employment.salaryPeriod, Number(f)), v);
  }
  for (const s of parity.stipends) assert.equal(R.stipend(s.level, s.score), s.expect);
});

const journeyDir = path.join(BUILD, "career_journey");
const journeys = fs.existsSync(journeyDir) ? fs.readdirSync(journeyDir).filter((f) => f.endsWith(".json")) : [];
if (required && journeys.length === 0) throw new Error("build/career_journey is empty.");

for (const f of journeys) {
  const j = JSON.parse(fs.readFileSync(path.join(journeyDir, f), "utf8"));
  test(`full journey (${j.dept}): the server's wallet equals the app's`, () => {
    let state = emptyState();
    let now = j.nowMs;
    for (const e of j.events) {
      now += 60 * 1000;
      ({ state } = applyAction(state, e.action, e.payload, e.opId, now));
    }
    const a = Object.values(state.applications)[0];
    assert.equal(a.screening.score, j.expect.screening);
    assert.equal(a.interview.overall, j.expect.interview);
    assert.equal(a.offerSalary, j.expect.offerSalary);
    const job = Object.values(state.employments)[0];
    assert.equal(job.periodsPaid, j.expect.paychecks);
    assert.equal(job.salary, j.expect.salary);
    assert.equal(state.balanceCents, j.expect.balanceCents);

    // Replaying the same reports (a retry) changes nothing.
    const before = JSON.stringify(state);
    for (const e of j.events) ({ state } = applyAction(state, e.action, e.payload, e.opId, now));
    assert.equal(JSON.stringify(state), before);
  });
}
